mapper.select:
SELECT 
FROM sys_file f

    INNER JOIN sys_file_favorite fav ON fav.file_id = f.file_id AND fav.user_id = #{query.currentUserId}


    INNER JOIN sys_file_recent r ON r.file_id = f.file_id AND r.user_id = #{query.currentUserId}

WHERE f.del_flag = '0'

    AND f.folder_id = #{query.folderId}


    AND f.category = #{query.category}


    AND f.media_type = #{query.mediaType}



        AND (
            f.file_name LIKE CONCAT('%', #{query.keyword}, '%')
            OR IFNULL(f.remark, '') LIKE CONCAT('%', #{query.keyword}, '%')
            OR EXISTS (
                SELECT 1 FROM sys_file_tag_rel tr
                INNER JOIN sys_file_tag t ON t.tag_id = tr.tag_id
                WHERE tr.file_id = f.file_id
                  AND t.tag_name LIKE CONCAT('%', #{query.keyword}, '%')

                    AND tr.create_by_user_id = #{query.currentUserId}

            )
        )


        AND f.file_name LIKE CONCAT('%', #{query.fileName}, '%')



    AND f.create_by LIKE CONCAT('%', #{query.createBy}, '%')


    AND f.create_time >= #{query.beginTime}


    AND f.create_time <= #{query.endTime}


    AND EXISTS (
        SELECT 1 FROM sys_file_tag_rel tr
        WHERE tr.file_id = f.file_id
          AND tr.tag_id = #{query.tagId}
          AND tr.create_by_user_id = #{query.currentUserId}
    )




        ORDER BY r.access_time DESC


        ORDER BY fav.create_time DESC


        ORDER BY f.create_time DESC

SELECT 
FROM sys_file
WHERE del_flag = '2'

    AND category = #{query.category}


    AND file_name LIKE CONCAT('%', #{query.fileName}, '%')


    AND delete_by LIKE CONCAT('%', #{query.deleteBy}, '%')


    AND delete_time >= #{query.beginTime}


    AND delete_time <= #{query.endTime}


ORDER BY delete_time DESC

SELECT COUNT(1)
FROM sys_file
WHERE object_name = #{objectName}

    AND file_id <> #{excludeFileId}

